// ===============================================================================
// DAEMIND SRE - PARSER CANÔNICO DA AMAZON SP-API (PRIME, FBA, BUYER_INFO)
// ===============================================================================
const crypto = require('crypto');
const body = $json.body || $json;

const amazonOrderId = body.AmazonOrderId || body.amazon_order_id || Date.now().toString();
const buyerInfo = body.BuyerInfo || body.buyer_info || {};
let rawPhone = (buyerInfo.BuyerPhone || body.ShippingAddress?.Phone || '').toString().replace(/\D/g, '');
if (rawPhone.length >= 10 && rawPhone.length <= 11) {
  rawPhone = '55' + rawPhone;
}

const clienteNome = (buyerInfo.BuyerName || body.ShippingAddress?.Name || 'Cliente Amazon').trim();
const clienteEmail = (buyerInfo.BuyerEmail || '').trim().toLowerCase();

const numeroPedido = parseInt(amazonOrderId.replace(/\D/g, '') || Date.now(), 10);
const valorTotal = parseFloat(body.OrderTotal?.Amount || body.order_total || 0);
const orderStatus = (body.OrderStatus || body.order_status || '').toLowerCase();
const isPrime = Boolean(body.IsPrime || body.is_prime);
const fulfillmentChannel = body.FulfillmentChannel || 'MFN';

let statusOperacional = 'Pendente';
if (['unshipped', 'partiallyshipped', 'shipped'].includes(orderStatus)) {
  statusOperacional = 'Pago';
} else if (['canceled'].includes(orderStatus)) {
  statusOperacional = 'Cancelado';
}

const dedupHash = crypto.createHash('sha256').update(`amazon_${amazonOrderId}_${statusOperacional}_${valorTotal}`).digest('hex');

return [{
  json: {
    dedup_hash: dedupHash,
    amazon_order_id: amazonOrderId,
    numero_pedido: numeroPedido,
    cliente_nome: clienteNome,
    cliente_email: clienteEmail,
    cliente_whatsapp: rawPhone,
    valor_total: valorTotal,
    is_prime: isPrime,
    fulfillment_channel: fulfillmentChannel,
    status_operacional: statusOperacional
  }
}];
